ee664f4f6929e222d63ac7fae62e351b0f2f9c3c:
query Product($sku: String!) {
  product(sku: $sku) {
    id
    sku
    name
    category {
      id
      name
      parentId
    }
    attributes {
      key
      values
    }
    primaryUnit {
      code
      name
      precision
    }
    units {
      code
      name
      precision
    }
    price {
      unitPrice {
        amount
        currency
      }
      unitCode
      quantity
      minQuantity
    }
  }
}

1f638264b5b6c9b2579142c8e5242adf3697b6c5:
query ProductPrice($sku: String!, $unitCode: String!, $quantity: String!) {
  product(sku: $sku) {
    id
    price(unitCode: $unitCode, quantity: $quantity) {
      unitPrice {
        amount
        currency
      }
      unitCode
      quantity
      minQuantity
    }
  }
}

575ca7a982548bbf26720b315e940c964f3ef97c:
query Products($categoryId: ID, $includeSubcategories: Boolean, $first: Int, $after: String) {
  products(
    categoryId: $categoryId
    includeSubcategories: $includeSubcategories
    first: $first
    after: $after
  ) {
    nodes {
      id
      sku
      name
      category {
        id
        name
      }
      primaryUnit {
        code
        name
        precision
      }
      price {
        unitPrice {
          amount
          currency
        }
        unitCode
      }
    }
    nextAfter
  }
}

d77bdbd9b2b7b0c4a7b2624b2cee9640bc91e3d5:
query Search($query: String!, $first: Int, $offset: Int) {
  search(query: $query, first: $first, offset: $offset) {
    nodes {
      match
      product {
        id
        sku
        name
        category {
          id
          name
        }
        primaryUnit {
          code
          name
          precision
        }
        price {
          unitPrice {
            amount
            currency
          }
          unitCode
        }
      }
    }
    nextOffset
  }
}

